//! The compiled markup of the crate (the module `compiled_xaml`, which the
//! styles of the library are loaded from) is generated by the build script of
//! the crate against the build-time type system: the type models of this
//! crate and of the crates it is built on, with none of them linked for its
//! types (docs/porting/xaml.md, 9.5.13 and 9.5.20). It is the twelve theme
//! documents, compiled as one group.
//!
//! The reference is not checked in: it is the output of the emitter run here
//! against the run-time type system, where every type is linked and registered
//! and the documents are read as the run-time loader reads them. The output of
//! the build is that text, byte for byte. Not a test of upstream.

use ferroui_base::styling::Styles;
use ferroui_base::Ref;
use ferroui_controls::testing::{TestServices, UnitTestApplication};
use ferroui_markup_xaml::RuntimeXamlLoaderConfiguration;
use ferroui_markup_xaml_loader::rust_emitter::{generate_file, XamlMetadata};

use crate::assets::documents;
use crate::ASSEMBLY;

/// Set in the process that compares the output of the build with the reference.
const REFERENCE_PROCESS: &str = "FERROUI_COLOR_PICKER_REFERENCE_PROCESS";

/// The name of the test that compares, as the test harness names it.
const REFERENCE_TEST: &str = "tests::compiled_xaml_tests::build_script_output_is_what_the_run_time_host_emits";

/// The root URI of the documents of the assembly.
fn root_uri() -> String {
    format!("ferres://{}/", ASSEMBLY.name)
}

/// The build script, which compiles against the type models, writes what the emitter writes
/// against the run-time type system: every theme document is compiled the same by both
/// hosts, and none is refused (a refused document fails the build of the crate).
///
/// The comparison runs in a process of its own (this test binary again, with this test
/// alone): the namespace information the emitter writes into a document lists the
/// assemblies registered in the process, and the other tests of the crate register the base
/// themes, which the build of the crate does not know.
#[test]
fn build_script_output_is_what_the_run_time_host_emits() {
    if std::env::var_os(REFERENCE_PROCESS).is_none() {
        let binary = std::env::current_exe().expect("the path of the test binary");
        let output = std::process::Command::new(binary)
            .args(["--exact", REFERENCE_TEST, "--nocapture", "--test-threads=1"])
            .env(REFERENCE_PROCESS, "1")
            .output()
            .expect("the test binary runs again");
        let (out, error) = (String::from_utf8_lossy(&output.stdout), String::from_utf8_lossy(&output.stderr));
        assert!(output.status.success() && out.contains("1 passed"), "the comparison failed in its own process:\n{out}\n{error}");
        return;
    }

    let _app = UnitTestApplication::start(TestServices::styled_window());
    crate::register_types();
    let documents = documents();
    let mut configuration = RuntimeXamlLoaderConfiguration::new();
    configuration.local_assembly = Some(&ASSEMBLY);
    // The upstream project is built with compiled bindings as the default of its documents.
    configuration.use_compiled_bindings_by_default = true;
    let file = generate_file(ASSEMBLY.name, &root_uri(), &documents, &configuration, &[]);
    let refused: Vec<String> =
        file.documents.iter().filter_map(|(name, reason)| reason.as_ref().map(|reason| format!("{name}: {reason}"))).collect();
    assert!(refused.is_empty(), "the run-time host refuses documents:\n{}", refused.join("\n"));

    let built = include_str!(concat!(env!("OUT_DIR"), "/xaml/compiled_xaml.rs"));
    if built != file.source {
        let line = built
            .lines()
            .zip(file.source.lines())
            .position(|(a, b)| a != b)
            .unwrap_or_else(|| built.lines().count().min(file.source.lines().count()));
        panic!("compiled_xaml.rs of the build script differs from the output of the run-time host (first difference at line {})", line + 1);
    }

    // The `.xamlmeta` of the build has the same documents, next to the type model of the crate.
    let text = std::fs::read_to_string(env!("FERROUI_XAMLMETA")).expect("the .xamlmeta of the build can be read");
    let built = XamlMetadata::parse(&text).expect("the .xamlmeta of the build is read");
    let expected = file.metadata(ASSEMBLY.crate_name, "::ferroui_controls_color_picker::compiled_xaml", &[]);
    assert_eq!((&built.name, &built.crate_name), (&expected.name, &expected.crate_name));
    assert!(built.documents == expected.documents, "the documents of the .xamlmeta of the build script differ from the ones of the run-time host");
    assert_eq!(built.documents.len(), documents.len());
}

/// The styles of the library are the two public documents: the loader table of the compiled
/// markup builds each from its compiled markup when it is asked for its URI, without regard
/// to case, and answers for nothing else (the resource dictionaries they merge are
/// internal, as upstream's `x:ClassModifier`, and are part of the two).
#[test]
fn the_loader_table_answers_the_public_documents() {
    let _app = UnitTestApplication::start(TestServices::styled_window());
    crate::register_types();
    let documents = documents();
    assert_eq!(documents.len(), 12);
    for (name, _) in &documents {
        let uri = format!("{}{name}", root_uri());
        let public = matches!(*name, "Themes/Fluent/Fluent.xaml" | "Themes/Simple/Simple.xaml");
        for uri in [uri.clone(), uri.to_uppercase()] {
            let loaded = crate::compiled_markup::try_load(None, &uri).unwrap_or_else(|error| panic!("{uri}: {}", error.message()));
            assert_eq!(loaded.is_some(), public, "{uri}");
            if let Some(loaded) = loaded {
                let styles = ferroui_base::metadata::from_markup_value::<Ref<Styles>>(&Some(loaded)).expect("the styles of the library");
                // The five control themes of the library, merged into the resources of the styles.
                assert_eq!(styles.resources().merged_dictionaries().count(), 0, "{uri}: a merge is resolved by the compiler");
                assert!(styles.resources().count() >= 5, "{uri}: {} resources", styles.resources().count());
            }
        }
    }
}
